/* Выполняет один SQL в Trino через REST (/v1/statement) и ждёт результата.
   Вход:  $json.sql
   Выход: { rows: [{колонка: значение}], update_count: число|null }
   Ошибка Trino → исключение → у вызывающей Execute Workflow ошибка (флоу ответит 5xx).

   Подключение — из переменных окружения n8n (нужен N8N_BLOCK_ENV_ACCESS_IN_NODE=false):
     TRINO_URL (https://trino.local:8443), TRINO_USER, TRINO_PASSWORD, TRINO_CATALOG, TRINO_SCHEMA
   Если в вашем n8n к Trino уже ходят иначе (своя нода, JDBC-шлюз) — используйте его,
   главное сохранить вход/выход. */
const sql = $input.first().json.sql;
if (!sql) throw new Error('trino_query: пустой sql');
const base = $env.TRINO_URL.replace(/\/$/, '');
const headers = {
  'X-Trino-User': $env.TRINO_USER,
  'X-Trino-Catalog': $env.TRINO_CATALOG,
  'X-Trino-Schema': $env.TRINO_SCHEMA,
  'X-Trino-Source': 'n8n-ta_save',
  Authorization: 'Basic ' + Buffer.from($env.TRINO_USER + ':' + $env.TRINO_PASSWORD).toString('base64'),
};
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

let res = await this.helpers.httpRequest({ method: 'POST', url: base + '/v1/statement', headers, body: sql, json: true });
let columns = null;
const data = [];
let updateCount = null;
const started = Date.now();
for (;;) {
  if (res.error) throw new Error('Trino: ' + res.error.errorName + ': ' + res.error.message);
  if (res.columns) columns = res.columns.map((c) => c.name);
  if (res.data) data.push(...res.data);
  if (res.updateCount != null) updateCount = res.updateCount;
  if (!res.nextUri) break;
  if (Date.now() - started > 60000) throw new Error('Trino: таймаут 60 с');
  if (!res.data) await sleep(200);
  res = await this.helpers.httpRequest({ method: 'GET', url: res.nextUri, headers, json: true });
}
const rows = columns ? data.map((r) => Object.fromEntries(columns.map((c, i) => [c, r[i]]))) : [];
// Для INSERT Trino отдаёт число вставленных строк в updateCount (а также строкой rows в колонке "rows").
if (updateCount == null && columns && columns[0] === 'rows' && rows.length === 1) updateCount = Number(rows[0].rows);
return [{ json: { rows, update_count: updateCount } }];
